public void testVersionEqualWithLeadingZeroes() {
    // versions with string lengths from 1 to 19
    String[] arr = new String[] { "0000000000000000001", "000000000000000001", "00000000000000001", "0000000000000001", "000000000000001", "00000000000001", "0000000000001", "000000000001", "00000000001", "0000000001", "000000001", "00000001", "0000001", "000001", "00001", "0001", "001", "01", "1" };
    checkVersionsArrayEqual(arr);
}

/**
 * Test all "0" versions are equal when starting with many leading zeroes regardless of string length
